def find_smallest_prime(nbr: int) -> int:
    """ Given a positive integer, find the smallest prime number greater than the
    given number.

    Use a greedy strategy: Keep incrementing nbr by 1 as long as the next prime
    value doesn't match the previous nbr. Once you hit the correct prime number
    stop looping.

    >>> find_smallest_prime(10)
    11
    >>> find_smallest_prime(15)
    17
    """
    if nbr == 2:
        return 3
    elif nbr == 1:
        return 2

    while True:
        nbr += 1
        if nbr >= 6:
            break

        for i in range(2, nbr):
            if nbr % i == 0:
                break

        else:
            return nbr


