def deepest_level(paren_string: str) -> int:
    """ Given the string representation of nested parentheses (or grouping operator of any kind like curly braces or brackets),
    this method returns the maximum level of nesting from the string.
    For the given example '(()())', the maximum level would be 2.
    """
    if len(paren_string) == 0:
        return 0
    stack = []
    current_depth = 0
    for char in paren_string:
        if char == "(":
            stack.append(current_depth)
