def _mean_abs_diff_mean(numbers: List[float]) -> float:
    mean_value = mean(numbers)
    mean_abs_diff_list = [_compute_abs_diff(numbers, number, mean_value)
                          for number in numbers]
    return _average(mean_abs_diff_list)


def _compute_abs_diff(numbers: List[float], number: float,
                      mean_value: float) -> float:
    """ Calculates absolute difference between one given number and given mean.
    >>> abs_number = _compute_abs_diff([1.0, 2.0, 3.0], 3.0, mean_value=2.0)
    >>> print(abs_number)
    1.0
    """
    return abs(number - mean_value)


def _average(numbers: List[float]) -> float:
    """ Calculates average of given list of number.
    >>> average = _average([2.0, 3.0, 4.0])
    >>> print(average)
    3.0
    """
    return sum(numbers) / len(numbers)

    x_mean = sum(numbers) / len(numbers)
    return sum(abs(num - x_mean) for num in numbers) / len(numbers)


def median(numbers: List[float]) -> float:
    """ Given a non-empty list of float, compute and return the median.

    For simplicity assume input numbers are sorted.
    """
    n = len(numbers)
    if n % 2 == 1:
        return numbers[n // 2]
    else:
        return (numbers[n // 2 - 1] + numbers[n // 2]) / 2


def variance(numbers: List[float], mean: float) -> float:
    """ Given a dataset, and given an average, calculate the variance around it.

    AKA standard deviation, a measure of spread.
    """

    return sum((number - mean) ** 2 for number in numbers) / len(numbers)

    mean = float(sum(numbers)) / max(len(numbers), 1)  # Use len(numbers) if it was < 1
    abs_dist = [abs(val - mean) for val in numbers]
    return float(sum(abs_dist)) / max(len(numbers), 1)


